<?php
declare(strict_types=1);
function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function redirect(string $u):never{header('Location: '.$u);exit;}
function csrf_token():string{if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));return $_SESSION['csrf_token'];}
function csrf_field():string{return '<input type="hidden" name="csrf_token" value="'.h(csrf_token()).'">';}
function verify_csrf():void{$s=(string)($_POST['csrf_token']??'');if($s===''||!hash_equals((string)($_SESSION['csrf_token']??''),$s))throw new RuntimeException('Session expired. Refresh and try again.');}
function current_user(PDO $db):?array{if(empty($_SESSION['user_id']))return null;$s=$db->prepare('SELECT id,username,name,address,phone,email,role,is_active FROM users WHERE id=?');$s->execute([(int)$_SESSION['user_id']]);$u=$s->fetch();if(!$u||(int)$u['is_active']!==1){unset($_SESSION['user_id']);return null;}return $u;}
function require_user(PDO $db):array{$u=current_user($db);if(!$u)redirect('index.php?route=login');return $u;}
function require_admin(PDO $db):array{$u=require_user($db);if($u['role']!=='admin'){http_response_code(403);exit('Administrator access required.');}return $u;}
function setting(PDO $db,string $key,string $default=''):string{try{$s=$db->prepare('SELECT setting_value FROM settings WHERE setting_key=?');$s->execute([$key]);$v=$s->fetchColumn();return $v===false?$default:(string)$v;}catch(Throwable $e){return $default;}}
function upload_file(string $field,string $folder,array $allowed):?string{if(!isset($_FILES[$field])||$_FILES[$field]['error']===UPLOAD_ERR_NO_FILE)return null;$f=$_FILES[$field];if($f['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Upload failed; check file size and server upload limits.');if((int)$f['size']>APP_MAX_UPLOAD)throw new RuntimeException('Maximum file size is 100 MB.');$ext=strtolower(pathinfo((string)$f['name'],PATHINFO_EXTENSION));if(!in_array($ext,$allowed,true))throw new RuntimeException('Unsupported file extension.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$safeMimes=['image/jpeg','image/png','image/webp','audio/mpeg','audio/wav','audio/x-wav','audio/ogg','audio/mp4','audio/aac','audio/flac','video/mp4','video/webm','video/ogg','video/quicktime','application/octet-stream'];if(!in_array($mime,$safeMimes,true))throw new RuntimeException('File type could not be verified.');$dir=__DIR__.'/uploads/'.$folder;if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('Cannot create upload directory.');$name=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Could not save upload.');return 'uploads/'.$folder.'/'.$name;}
